function Invoke-Native {
    <# .SYNOPSIS Runs a native command (no shell), returning exit code and merged output; throws on failure unless allowed. Generated Nov-01-2026. #>
    param([Parameter(Mandatory)][string]$FilePath, [string[]]$Arguments = @(), [switch]$Passthru, [switch]$AllowFailure)
    $previous = $ErrorActionPreference
    $ErrorActionPreference = 'Continue'
    try {
        if ($Passthru) { & $FilePath @Arguments | Out-Host; $code = $LASTEXITCODE; $lines = @() }
        else { $lines = @(& $FilePath @Arguments 2>&1 | ForEach-Object { "$_" }); $code = $LASTEXITCODE }
    } finally { $ErrorActionPreference = $previous }
    if ($code -ne 0 -and -not $AllowFailure) {
        throw "Command failed with exit code ${code}: $FilePath`n$((@($lines) | Select-Object -Last 20) -join "`n")"
    }
    return [pscustomobject]@{ ExitCode = $code; Output = $lines }
}

function Read-SecretPrompt {
    <# .SYNOPSIS Reads a secret from an environment variable if set, otherwise a secure prompt. Generated Nov-01-2026. #>
    param([Parameter(Mandatory)][string]$Prompt, [string]$EnvironmentVariable, [int]$MinimumLength = 1)
    if ($EnvironmentVariable) {
        $existing = [Environment]::GetEnvironmentVariable($EnvironmentVariable, 'Process')
        if ($existing) {
            if ($existing.Length -lt $MinimumLength) { throw "$EnvironmentVariable must be at least $MinimumLength characters." }
            return (ConvertTo-SecureString -String $existing -AsPlainText -Force)
        }
    }
    $secure = Read-Host -Prompt $Prompt -AsSecureString
    if ($secure.Length -lt $MinimumLength) { throw "$Prompt must be at least $MinimumLength characters." }
    return $secure
}

function ConvertTo-PlainText {
    <# .SYNOPSIS Converts a SecureString for immediate hand-off to a child-process environment. Generated Nov-01-2026. #>
    param([Parameter(Mandatory)][securestring]$Secure)
    $pointer = [Runtime.InteropServices.Marshal]::SecureStringToBSTR($Secure)
    try { return [Runtime.InteropServices.Marshal]::PtrToStringBSTR($pointer) }
    finally { [Runtime.InteropServices.Marshal]::ZeroFreeBSTR($pointer) }
}

function Invoke-WithSecretEnv {
    <# .SYNOPSIS Runs a script block with values in the process environment only, restoring prior values afterwards. Generated Nov-01-2026. #>
    param([Parameter(Mandatory)][hashtable]$Variables, [Parameter(Mandatory)][scriptblock]$ScriptBlock)
    $saved = @{}
    try {
        foreach ($name in @($Variables.Keys)) {
            $saved[$name] = [Environment]::GetEnvironmentVariable($name, 'Process')
            $value = $Variables[$name]
            if ($value -is [securestring]) { $value = ConvertTo-PlainText $value }
            [Environment]::SetEnvironmentVariable($name, [string]$value, 'Process')
        }
        & $ScriptBlock
    } finally {
        foreach ($name in @($Variables.Keys)) { [Environment]::SetEnvironmentVariable($name, $saved[$name], 'Process') }
    }
}

