function Compare-VersionAtLeast {
    <# .SYNOPSIS Returns true when a dotted version string is at least the minimum. Generated Nov-01-2026. #>
    param([Parameter(Mandatory)][string]$Actual, [Parameter(Mandatory)][string]$Minimum)
    return ([version](($Actual.TrimStart('v') -split '[^0-9.]')[0])) -ge ([version]$Minimum)
}

function Get-NodeInfo {
    <# .SYNOPSIS Detects Node.js path, version and architecture. Generated Nov-01-2026. #>
    param([string]$MinimumVersion = '24.13.0')
    $candidates = @()
    $cmd = Get-Command node.exe -ErrorAction SilentlyContinue
    if ($cmd) { $candidates += $cmd.Source }
    $default = Join-Path $env:ProgramFiles 'nodejs\node.exe'
    if (Test-Path -LiteralPath $default) { $candidates += $default }
    foreach ($path in ($candidates | Select-Object -Unique)) {
        $run = Invoke-Native -FilePath $path -Arguments @('-p', 'process.version+String.fromCharCode(32)+process.arch') -AllowFailure
        if ($run.ExitCode -eq 0 -and $run.Output) {
            $parts = ($run.Output | Select-Object -First 1) -split ' '
            return [pscustomobject]@{
                Path = $path; Version = $parts[0].TrimStart('v'); Architecture = $parts[1]
                Ok = ((Compare-VersionAtLeast $parts[0] $MinimumVersion) -and $parts[1] -eq 'x64')
                UnderProgramFiles = $path.StartsWith($env:ProgramFiles, [StringComparison]::OrdinalIgnoreCase)
            }
        }
    }
    return $null
}

function Get-PsqlInfo {
    <# .SYNOPSIS Finds psql.exe on PATH or under Program Files\PostgreSQL and reads its major version. Generated Nov-01-2026. #>
    param([string]$OverridePath)
    $paths = @()
    if ($OverridePath) { $paths += $OverridePath }
    $cmd = Get-Command psql.exe -ErrorAction SilentlyContinue
    if ($cmd) { $paths += $cmd.Source }
    $root = Join-Path $env:ProgramFiles 'PostgreSQL'
    if (Test-Path -LiteralPath $root) {
        $paths += Get-ChildItem -LiteralPath $root -Directory -ErrorAction SilentlyContinue |
            Sort-Object { [int](($_.Name -replace '\D', '0')) } -Descending |
            ForEach-Object { Join-Path $_.FullName 'bin\psql.exe' }
    }
    foreach ($path in ($paths | Where-Object { Test-Path -LiteralPath $_ } | Select-Object -Unique)) {
        $run = Invoke-Native -FilePath $path -Arguments @('--version') -AllowFailure
        if ($run.ExitCode -eq 0 -and ($run.Output -join ' ') -match '(\d+)(\.\d+)*') {
            return [pscustomobject]@{ Path = $path; Major = [int]$Matches[1]; Text = ($run.Output | Select-Object -First 1) }
        }
    }
    return $null
}

