function Save-VerifiedDownload {
    <# .SYNOPSIS Downloads from a trusted host and enforces a published hash and/or Authenticode publisher; deletes the file on failure. Generated Nov-01-2026. #>
    param(
        [Parameter(Mandatory)][string]$Url, [Parameter(Mandatory)][string]$FileName,
        [string]$ExpectedHash, [ValidateSet('SHA256', 'SHA1')][string]$HashAlgorithm = 'SHA256', [string]$PublisherPattern
    )
    if (-not (Test-TrustedDownloadUrl $Url)) { throw "Refusing download from untrusted or non-HTTPS URL: $Url" }
    if (-not $ExpectedHash -and -not $PublisherPattern) { throw 'A published hash or required signer is mandatory for downloads.' }
    [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
    $target = Join-Path (Get-DownloadDirectory) $FileName
    Invoke-WebRequest -UseBasicParsing -Uri $Url -OutFile $target
    try {
        if ($ExpectedHash) {
            $actual = (Get-FileHash -LiteralPath $target -Algorithm $HashAlgorithm).Hash
            if ($actual -ne $ExpectedHash.ToUpperInvariant()) { throw "$HashAlgorithm mismatch for $FileName. Expected $ExpectedHash, got $actual." }
        }
        if ($PublisherPattern) {
            $signature = Get-AuthenticodeSignature -LiteralPath $target
            if ($signature.Status -ne 'Valid') { throw "Authenticode signature of $FileName is $($signature.Status)." }
            if ($signature.SignerCertificate.Subject -notmatch $PublisherPattern) { throw "Unexpected signer for ${FileName}: $($signature.SignerCertificate.Subject)" }
        }
    } catch { Remove-Item -LiteralPath $target -Force -ErrorAction SilentlyContinue; throw }
    return $target
}

function ConvertFrom-NodeShasums {
    <# .SYNOPSIS Finds the x64 MSI name and SHA-256 in a nodejs.org SHASUMS256.txt body. Generated Nov-01-2026. #>
    param([Parameter(Mandatory)][string]$Text)
    foreach ($line in ($Text -split "`n")) {
        if ($line.Trim() -match '^([0-9a-fA-F]{64})\s+(node-v(\d+\.\d+\.\d+)-x64\.msi)$') {
            return [pscustomobject]@{ Sha256 = $Matches[1].ToUpperInvariant(); FileName = $Matches[2]; Version = $Matches[3] }
        }
    }
    throw 'No node x64 MSI entry found in SHASUMS256.txt.'
}

function Install-NodeRuntime {
    <# .SYNOPSIS After approval, installs the latest Node 24 x64 MSI using nodejs.org's published SHA-256 and an OpenJS Foundation signature check. Generated Nov-01-2026. #>
    [CmdletBinding(SupportsShouldProcess)]
    param()
    $base = 'https://nodejs.org/dist/latest-v24.x'
    $detail = "Downloads $base/SHASUMS256.txt and the x64 MSI listed there; verifies SHA-256 and signature; runs msiexec silently (system-wide change)."
    if (-not (Request-Approval -Action 'Install Node.js 24 LTS (x64)' -Target 'this machine' -Detail $detail)) { return $false }
    [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
    $entry = ConvertFrom-NodeShasums -Text (Invoke-WebRequest -UseBasicParsing -Uri "$base/SHASUMS256.txt").Content
    $file = Save-VerifiedDownload -Url "$base/$($entry.FileName)" -FileName $entry.FileName -ExpectedHash $entry.Sha256 -PublisherPattern 'OpenJS Foundation'
    Invoke-Native -FilePath 'msiexec.exe' -Arguments @('/i', $file, '/qn', '/norestart') | Out-Null
    return $true
}

function Install-JdkRuntime {
    <# .SYNOPSIS After approval, installs Microsoft Build of OpenJDK, verifying the vendor SHA-256 sidecar when reachable plus the Microsoft signature. Generated Nov-01-2026. #>
    [CmdletBinding(SupportsShouldProcess)]
    param([ValidateSet(17, 21, 25)][int]$Major = 17)
    $url = "https://aka.ms/download-jdk/microsoft-jdk-$Major-windows-x64.msi"
    if (-not (Request-Approval -Action "Install JDK $Major" -Target 'this machine' -Detail "Downloads $url, verifies Microsoft signature and vendor .sha256sum.txt, runs msiexec silently.")) { return $false }
    $hash = $null
    try {
        [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
        $body = (Invoke-WebRequest -UseBasicParsing -Uri "$url.sha256sum.txt").Content
        if ($body -is [byte[]]) { $body = [Text.Encoding]::UTF8.GetString($body) }
        if ($body -match '(?i)\b([0-9a-f]{64})\b') { $hash = $Matches[1] }
    } catch { Write-Warning 'Vendor SHA-256 sidecar unavailable; relying on the mandatory Authenticode signature check.' }
    $splat = @{ Url = $url; FileName = "microsoft-jdk-$Major-windows-x64.msi"; PublisherPattern = 'Microsoft Corporation' }
    if ($hash) { $splat.ExpectedHash = $hash }
    $file = Save-VerifiedDownload @splat
    Invoke-Native -FilePath 'msiexec.exe' -Arguments @('/i', $file, '/qn', '/norestart', 'ADDLOCAL=FeatureMain,FeatureEnvironment,FeatureJavaHome') | Out-Null
    return $true
}



function ConvertTo-DotEnvValue {
    <# .SYNOPSIS Quotes a value for Node's --env-file parser (single, double or backtick quotes; no escapes are interpreted in single/backtick quotes); rejects line breaks and values that cannot be represented. Generated Nov-01-2026. #>
    param([Parameter(Mandatory)][AllowEmptyString()][string]$Value)
    if ($Value -match "[\r\n\0]") { throw 'Environment values must not contain line breaks or NUL.' }
    if ($Value -match '^[A-Za-z0-9_./:@+=,-]*$') { return $Value }
    if ($Value.IndexOf("'") -lt 0) { return "'$Value'" }
    if ($Value.IndexOf('`') -lt 0) { return '`' + $Value + '`' }
    if ($Value.IndexOf('"') -lt 0) { return '"' + ($Value -replace '\\', '\\') + '"' }
    throw "Value contains all of ', `` and `"; choose a password without one of these characters so Node's env-file parser reads it exactly."
}

function ConvertFrom-DotEnv {
    <# .SYNOPSIS Parses dotenv text the way Node's --env-file does for validation: export prefix, comments, single/double/backtick quotes and \n in double quotes. Returns a hashtable. Generated Nov-01-2026. #>
    param([Parameter(Mandatory)][AllowEmptyString()][string]$Text)
    $result = @{}
    foreach ($line in ($Text -split "\r?\n")) {
        if ($line -match '^\s*(?:export\s+)?([A-Za-z_][A-Za-z0-9_.-]*)\s*=\s*(.*)$') {
            $name = $Matches[1]; $raw = $Matches[2].Trim()
            if ($raw -match "^'(.*)'(?:\s+#.*)?$" -or $raw -match '^`(.*)`(?:\s+#.*)?$') { $value = $Matches[1] }
            elseif ($raw -match '^"(.*)"(?:\s+#.*)?$') { $value = $Matches[1].Replace('\n', "`n").Replace('\\', '\') }
            else { $value = ($raw -replace '\s+#.*$', '') }
            $result[$name] = $value
        }
    }
    return $result
}
